<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Dynamic Page</title>
    <style>
        /* Style for the heading */
        .dynamic-heading {
            font-size: 24px;
            text-align: right;
            background-color: #ff0000; /* Initial background color */
            transition: background-color 0.5s ease;
        }

        /* Style for the link */
        .responsive-link {
            text-decoration: none;
            color: red;
            transition: transform 0.3s ease, color 0.3s ease;
        }

        /* Hover effect for the link */
        .responsive-link:hover {
            transform: rotate(45deg);
            color: linear-gradient(to right, red, blue);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }
    </style>
</head>
<body>
    <h1 class="dynamic-heading">Welcome to the Dynamic Page</h1>
    <a href="https://example.com" class="responsive-link" id="responsiveLink">Click Me</a>

    <script>
        // Get the heading element
        const heading = document.querySelector('.dynamic-heading');

        // Array of colors to cycle through
        const colors = ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#00ffff', '#ff00ff'];

        // Function to change background color every 2 seconds
        function changeBackgroundColor() {
            const randomColor = colors[Math.floor(Math.random() * colors.length)];
            heading.style.backgroundColor = randomColor;
        }

        // Start the color change interval
        setInterval(changeBackgroundColor, 2000);

        // Get the link element
        const link = document.getElementById('responsiveLink');

        // Function to check if the user is on a mobile device with screen width < 600px
        function isMobileDevice() {
            return window.innerWidth < 600;
        }

        // Function to handle link click based on device
        function handleLinkClick(event) {
            if (isMobileDevice()) {
                // Open link in new tab for mobile devices
                event.preventDefault();
                window.open(event.target.href, '_blank');
            }
        }

        // Add click event listener to the link
        link.addEventListener('click', handleLinkClick);

        // Function to update the link behavior based on window resize
        function updateLinkBehavior() {
            if (isMobileDevice()) {
                // If it's a mobile device, ensure the link opens in a new tab
                link.addEventListener('click', handleLinkClick);
            } else {
                // If it's not a mobile device, remove the event listener
                link.removeEventListener('click', handleLinkClick);
            }
        }

        // Initial check for link behavior
        updateLinkBehavior();

        // Add event listener for window resize to update behavior
        window.addEventListener('resize', updateLinkBehavior);
    </script>
</body>
</html>
```

