```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <stdexcept>

// Function to merge two sorted arrays in-place with a single pointer
void mergeSortedArraysInPlace(std::vector<int>& arr1, std::vector<int>& arr2) {
    // Check for invalid inputs
    if (arr1.empty() || arr2.empty()) {
        throw std::invalid_argument("Both arrays must be non-empty.");
    }

    // Get the sizes of the arrays
    int n = arr1.size();
    int m = arr2.size();

    // Check if the arrays are sorted
    for (int i = 1; i < n; ++i) {
        if (arr1[i] < arr1[i - 1]) {
            throw std::invalid_argument("First array is not sorted.");
        }
    }
    for (int i = 1; i < m; ++i) {
        if (arr2[i] < arr2[i - 1]) {
            throw std::invalid_argument("Second array is not sorted.");
        }
    }

    // Ensure that arr1 is the larger array to avoid overwriting
    if (n < m) {
        std::swap(arr1, arr2);
        std::swap(n, m);
    }

    // Merge the two arrays in-place
    int i = 0; // Pointer for arr2
    int j = 0; // Pointer for arr1
    int k = 0; // Pointer for the merged array

    // Merge the two arrays using a single pointer
    while (i < m && j < n) {
        if (arr2[i] <= arr1[j]) {
            arr1[k++] = arr2[i++];
        } else {
            arr1[k++] = arr1[j++];
        }
    }

    // Copy the remaining elements from arr2
    while (i < m) {
        arr1[k++] = arr2[i++];
    }

    // Copy the remaining elements from arr1
    while (j < n) {
        arr1[k++] = arr1[j++];
    }
}

int main() {
    try {
        std::vector<int> arr1 = {1, 3, 5, 7};
        std::vector<int> arr2 = {2, 4, 6, 8};

        mergeSortedArraysInPlace(arr1, arr2);

        // Print the merged array
        for (int num : arr1) {
            std::cout << num << " ";
        }
        std::cout << std::endl;
    } catch (const std::invalid_argument& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
