class Maybe:
    """
    A monad for handling computations that may result in an error or absence of a value.
    """
    def __init__(self, value):
        """
        Initialize the Maybe with a value.
        :param value: The value to be wrapped in Maybe.
        """
        self.value = value

    def bind(self, func):
        """
        Apply a function to the value if it exists; otherwise, return None.
        :param func: A function that takes a value and returns a Maybe.
        :return: A Maybe instance.
        """
        return func(self.value) if self.value is not None else Maybe(None)

